console.assert(format("hello", { maxLength: 10 }) === "hello", "under limit is untouched");
console.assert(format("hello", { maxLength: 5 }) === "hello", "exactly at limit is untouched");
console.assert(format("hello there world", { maxLength: 12 }) === "hello...", "cuts back to word boundary");
console.assert(format("antidisestablishmentarianism", { maxLength: 10 }) === "antidis...", "hard cut when no word boundary");
console.assert(format("hello there world", { maxLength: 12 }).length <= 12, "ellipsis counts toward the budget");
console.assert(format("hello there world", { maxLength: 12, prefix: ">> " }) === ">> hello...", "prefix survives truncation");

console.log("All tests passed");

// Truncate before the decorators so an explicitly requested prefix or
// suffix is never the thing that gets cut off.
if (typeof options.maxLength === "number" && result.length > options.maxLength) {
  // The ellipsis is spent from the budget, so maxLength is a real guarantee.
  const hardCut = result.slice(0, Math.max(0, options.maxLength - 3));
  const lastSpace = hardCut.lastIndexOf(" ");
  // A window with no word boundary would leave nothing but the ellipsis,
  // so fall back to cutting mid-word.
  const body = lastSpace > 0 ? hardCut.slice(0, lastSpace).trimEnd() : hardCut;
  result = (body + "...").slice(0, options.maxLength);
}

if (options.prefix) {
  result = options.prefix + result;
}

